    public static function run(string $scenario,string $requestedBy='owner'):array{
        $defs=self::scenarios();if(!isset($defs[$scenario]))throw new RuntimeException('runtime_validation_scenario_invalid');$d=$defs[$scenario];db()->prepare("INSERT INTO runtime_validation_runs(scenario_key,label_ar,mode_key,state,requested_by,started_at) VALUES (?,?,?,'running',?,NOW())")->execute([$scenario,$d['label'],$d['mode'],$requestedBy]);$id=(int)db()->lastInsertId();$steps=[];try{$steps=match($scenario){'core_integrations'=>self::core($id),'full_integrations'=>self::fullIntegrations($id),'company_flow'=>self::company($id),'agency_flow'=>self::agency($id),'samir_flow'=>self::samir($id),'mona_flow'=>self::mona($id),'company_synthetic_flow'=>self::syntheticCompany($id),'agency_synthetic_flow'=>self::syntheticAgency($id),'social_synthetic_flow'=>self::syntheticSocial($id),'v17_core_acceptance'=>self::v20CoreAcceptance($id),'v20_core_acceptance'=>self::v20CoreAcceptance($id)};$failed=count(array_filter($steps,static fn($x)=>$x['state']==='failed'));$blocked=count(array_filter($steps,static fn($x)=>in_array($x['state'],['blocked','skipped'],true)));$passed=count(array_filter($steps,static fn($x)=>$x['state']==='passed'));$state=$failed?'failed':($blocked?'partial':'passed');$summary=['passed'=>$passed,'failed'=>$failed,'blocked'=>$blocked,'total'=>count($steps)];db()->prepare('UPDATE runtime_validation_runs SET state=?,summary_json=?,completed_at=NOW() WHERE id=?')->execute([$state,j($summary),$id]);return ['run_id'=>$id,'scenario'=>$scenario,'state'=>$state,'summary'=>$summary,'steps'=>$steps];}catch(Throwable $e){db()->prepare("UPDATE runtime_validation_runs SET state='failed',summary_json=?,completed_at=NOW() WHERE id=?")->execute([j(['error'=>pb_substr(Security::redactSecrets($e->getMessage()),0,300)]),$id]);throw $e;}
    }
    private static function add(int $runId,string $key,string $label,string $state,string $details,array $evidence=[]):array{if(!in_array($state,['passed','failed','blocked','skipped'],true))$state='failed';db()->prepare('INSERT INTO runtime_validation_steps(run_id,step_key,label_ar,state,details_text,evidence_json) VALUES (?,?,?,?,?,?)')->execute([$runId,$key,$label,$state,pb_substr($details,0,8000),$evidence?j($evidence):null]);return ['key'=>$key,'label'=>$label,'state'=>$state,'details'=>$details,'evidence'=>$evidence];}
    private static function probeResult(array $r):array{
        $stateRaw=pb_strtolower(trim((string)($r['state']??'')));
        $ok=array_key_exists('ok',$r)?(bool)$r['ok']:null;
        $error=trim((string)($r['error']??$r['result_code']??$r['code']??''));
        $issues=$r['issues']??null;
        if($ok===false||in_array($stateRaw,['failed','error','unhealthy'],true)){
            $hint=pb_strtolower($error.' '.(is_array($issues)?implode(' ',array_map('strval',$issues)):(string)$issues));
            $blocked=str_contains($hint,'not_configured')||str_contains($hint,'missing')||str_contains($hint,'disabled')||str_contains($hint,'unavailable');
            $details=$error!==''?$error:($issues?('issues: '.pb_substr(is_array($issues)?j($issues):(string)$issues,0,700)):'Probe returned a failure state.');
            return [$blocked?'blocked':'failed',$details];
        }
        if(in_array($stateRaw,['blocked','skipped','partial','pending','untested'],true)){
            $details=$error!==''?$error:('Probe returned state '.$stateRaw.'.');
            return [$stateRaw==='skipped'?'skipped':'blocked',$details];
        }
        if($ok===true||$stateRaw===''||in_array($stateRaw,['verified','passed','ok','healthy','success','completed'],true))return ['passed','Live probe succeeded.'];
        return ['blocked','Probe returned an unrecognized state: '.$stateRaw];
    }
    private static function probe(int $runId,string $key,string $label,callable $fn):array{try{$r=$fn();$evidence=is_array($r)?$r:['result'=>$r];[$state,$details]=is_array($r)?self::probeResult($r):['passed','Live probe succeeded.'];return self::add($runId,$key,$label,$state,$details,$evidence);}catch(Throwable $e){$msg=pb_substr(Security::redactSecrets($e->getMessage()),0,500);$low=pb_strtolower($msg);$blocked=str_contains($low,'not_configured')||str_contains($low,'missing')||str_contains($low,'disabled')||str_contains($low,'unavailable');return self::add($runId,$key,$label,$blocked?'blocked':'failed',$msg);}}
    private static function core(int $id):array{
        $out=[];$out[]=self::probe($id,'openrouter','OpenRouter inference',static fn()=>OpenRouterService::inferenceTest());$out[]=self::probe($id,'meta','WhatsApp Meta phone',static fn()=>MetaClient::test());$out[]=self::probe($id,'hostinger','Hostinger inventory',static function(){ $r=HostingerClient::websites();return ['website_count'=>count($r),'sample'=>array_slice(array_map(static fn($x)=>is_array($x)?array_intersect_key($x,array_flip(['domain','username','status'])):$x,$r),0,3)];});$out[]=self::probe($id,'browser','Browser automation bridge',static fn()=>BrowserAutomationService::test());$out[]=self::probe($id,'browser_qa','Browser QA bridge',static fn()=>BrowserQaService::test());$out[]=self::probe($id,'media','Media bridge',static fn()=>MediaBridgeClient::test());
        $last=(string)setting('runtime.worker_heartbeat_at','');$ts=utc_ts($last);$healthy=$ts!==false&&$ts>=time()-300;$out[]=self::add($id,'worker','Worker heartbeat',$healthy?'passed':'failed',$healthy?'Worker heartbeat is recent.':'Worker heartbeat is stale or missing.',['heartbeat_at'=>$last]);
        try{$h=db()->query("SELECT COUNT(*) samples,MIN(heartbeat_minute) first_at,MAX(heartbeat_minute) last_at FROM worker_heartbeat_log WHERE heartbeat_minute>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 6 HOUR)")->fetch()?:[];$samples=(int)($h['samples']??0);$first=(string)($h['first_at']??'');$lastSeen=(string)($h['last_at']??'');$span=0;if($first!==''&&$lastSeen!==''){$a=strtotime($first.' UTC');$b=strtotime($lastSeen.' UTC');if($a!==false&&$b!==false)$span=max(0,$b-$a);}$continuity=$samples>=6&&$span>=5*3600;$out[]=self::add($id,'worker_continuity','Worker six-hour continuity',$continuity?'passed':'blocked',$continuity?'Heartbeat history proves worker activity across at least five hours of the last six.':'There is not yet enough heartbeat history to prove multi-hour continuity. Leave the worker running and repeat this validation later.',['samples'=>$samples,'first_at'=>$first?:null,'last_at'=>$lastSeen?:null,'span_seconds'=>$span]);}catch(Throwable $e){$out[]=self::add($id,'worker_continuity','Worker six-hour continuity','blocked',pb_substr(Security::redactSecrets($e->getMessage()),0,400));}
        try{$site=HostingerClient::siteByDomain((string)(parse_url((string)config('app.base_url'),PHP_URL_HOST)?:'persebayt.com'));$crons=HostingerClient::cronJobs((string)$site['username']);$found=false;foreach($crons as $c){$raw=pb_strtolower(j($c));if(str_contains($raw,'worker')||str_contains($raw,'cron-worker')){$found=true;break;}}$out[]=self::add($id,'cron','Worker cron',$found?'passed':'failed',$found?'Worker cron entry found.':'No worker cron entry was identified.',['cron_count'=>count($crons)]);}catch(Throwable $e){$out[]=self::add($id,'cron','Worker cron','blocked',pb_substr(Security::redactSecrets($e->getMessage()),0,400));}
        return $out;
    }
