        try{$n=(int)db()->query("SELECT COUNT(*) FROM secure_vault_snapshots WHERE state='verified' AND CHAR_LENGTH(envelope_sha256)=64")->fetchColumn();$out[]=self::add($id,'encrypted_vault_snapshot','Encrypted current vault snapshot',$n>0?'passed':'failed',$n>0?'Encrypted vault envelope is preserved in the database without plaintext secrets.':'No verified encrypted vault snapshot is available.',['snapshots'=>$n]);}catch(Throwable $e){$out[]=self::add($id,'encrypted_vault_snapshot','Encrypted current vault snapshot','failed',pb_substr(Security::redactSecrets($e->getMessage()),0,300));}
        try{$n=(int)db()->query("SELECT COUNT(*) FROM secure_config_snapshots WHERE state='verified' AND CHAR_LENGTH(config_sha256)=64")->fetchColumn();$out[]=self::add($id,'encrypted_config_snapshot','Encrypted current config snapshot',$n>0?'passed':'failed',$n>0?'Encrypted config envelope and config hash are preserved.':'No verified encrypted config snapshot is available.',['snapshots'=>$n]);}catch(Throwable $e){$out[]=self::add($id,'encrypted_config_snapshot','Encrypted current config snapshot','failed',pb_substr(Security::redactSecrets($e->getMessage()),0,300));}
