        $out[]=self::add($id,'canonicalizer_service','Prompt canonicalizer service',class_exists('PromptCanonicalizerService')?'passed':'failed',class_exists('PromptCanonicalizerService')?'Prompt canonicalizer is available.':'Prompt canonicalizer service is missing.');
        $releaseOk=class_exists('ReleaseInfo')&&(ReleaseInfo::VERSION==='20.0.0-final-unified'||str_starts_with(ReleaseInfo::VERSION,'20.1.'));$out[]=self::add($id,'release20','Release 20/20.1 package marker',$releaseOk?'passed':'failed','Release marker is '.(class_exists('ReleaseInfo')?ReleaseInfo::VERSION:'missing').'.');
