    public static function scheduled():array{
        if(setting('runtime.validation.scheduler_enabled','1')==='0')return ['enabled'=>false,'runs'=>[]];$utc=new DateTimeImmutable('now',new DateTimeZone('UTC'));$hour=(int)$utc->format('G');$dow=(int)$utc->format('w');$dailyHour=max(0,min(23,(int)setting('runtime.validation.daily_hour_utc','2')));$weeklyDay=max(0,min(6,(int)setting('runtime.validation.weekly_day_utc','0')));$weeklyHour=max(0,min(23,(int)setting('runtime.validation.weekly_hour_utc','3')));$rows=[];try{$rows=db()->query("SELECT * FROM runtime_validation_scenarios WHERE enabled=1 ORDER BY scenario_key")->fetchAll();}catch(Throwable){$rows=[];}$map=['critical_integrations'=>'core_integrations','full_integrations'=>'full_integrations','company_synthetic_flow'=>'company_synthetic_flow','agency_synthetic_flow'=>'agency_synthetic_flow','social_synthetic_flow'=>'social_synthetic_flow','v17_core_acceptance'=>'v17_core_acceptance','v20_core_acceptance'=>'v20_core_acceptance'];$runs=[];
        foreach($rows as $r){$key=(string)$r['scenario_key'];$scenario=$map[$key]??$key;if(!isset(self::scenarios()[$scenario]))continue;$schedule=(string)$r['schedule_key'];if(!in_array($schedule,['daily','weekly'],true))continue;$due=false;if($schedule==='daily'&&$hour>=$dailyHour){$q=db()->prepare('SELECT MAX(started_at) FROM runtime_validation_runs WHERE scenario_key=?');$q->execute([$scenario]);$last=(string)($q->fetchColumn()?:'');$due=$last===''||substr($last,0,10)!==$utc->format('Y-m-d');}elseif($schedule==='weekly'&&$dow===$weeklyDay&&$hour>=$weeklyHour){$q=db()->prepare('SELECT MAX(started_at) FROM runtime_validation_runs WHERE scenario_key=?');$q->execute([$scenario]);$last=(string)($q->fetchColumn()?:'');$ts=$last!==''?utc_ts($last):false;$due=$ts===false||$ts<time()-6*86400;}if(!$due)continue;try{$runs[$key]=self::run($scenario,'scheduler');}catch(Throwable $e){$runs[$key]=['state'=>'failed','error'=>pb_substr(Security::redactSecrets($e->getMessage()),0,240)];}}
        return ['enabled'=>true,'runs'=>$runs,'checked_at'=>now_utc()];
    }

    public static function latest(int $limit=40):array{$limit=max(1,min(200,$limit));return db()->query('SELECT * FROM runtime_validation_runs ORDER BY id DESC LIMIT '.$limit)->fetchAll();}
    public static function details(int $id):array{$q=db()->prepare('SELECT * FROM runtime_validation_runs WHERE id=?');$q->execute([$id]);$run=$q->fetch();if(!$run)throw new RuntimeException('runtime_validation_not_found');$s=db()->prepare('SELECT * FROM runtime_validation_steps WHERE run_id=? ORDER BY id');$s->execute([$id]);return ['run'=>$run,'steps'=>$s->fetchAll()];}
